===== AddressNormalizer =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Normalizes a street address into a single canonical form used both for storage and for every
 * address comparison (household duplicate detection and the shared household id):
 * <ul>
 *   <li>leading and trailing whitespace is trimmed and internal whitespace runs are collapsed to a
 *       single space;</li>
 *   <li>the text is upper-cased;</li>
 *   <li>common trailing-type abbreviations are expanded as whole words: {@code ST -> STREET},
 *       {@code RD -> ROAD}, {@code AVE -> AVENUE}.</li>
 * </ul>
 * So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}. Returns {@code ""} for a
 * {@code null} or whitespace-only input, so callers can treat a blank-after-normalization address
 * as absent.
 */
final class AddressNormalizer {

    private AddressNormalizer() {
    }

    static String normalize(String raw) {
        if (raw == null) {
            return "";
        }
        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase();
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(expand(tokens[i]));
        }
        return sb.toString();
    }

    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}
===== OwnerIdentityKey =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code identityKey}: the single value all duplicate detection is expressed
 * through. Formatted {@code normalizedTelephone|email|householdId}, where the email and householdId
 * segments are empty when the owner has none. Two owners are the same identity when their whole
 * identityKey is equal; the telephone being part of the key means two members of one household
 * (same householdId) with different telephones have different keys and are both allowed.
 *
 * <p>The telephone is normalized to E.164 (the same way as {@link E164Telephone}) and the email is
 * trimmed and lower-cased, so differently-formatted values still produce the same key. The key is
 * computed identically for a not-yet-saved owner (in {@link CheckOwnerIdentityUnique}) and for the
 * response, so what a client reads back is exactly what collisions are judged on.
 */
public final class OwnerIdentityKey {

    private OwnerIdentityKey() {
    }

    /** The owner's identity key: {@code normalizedTelephone|email|householdId}. */
    public static String of(Owner owner) {
        return normalizeTelephone(owner.getTelephone()) + "|" + normalizeEmail(owner.getEmail())
                + "|" + (owner.getHouseholdId() == null ? "" : owner.getHouseholdId());
    }

    private static String normalizeTelephone(String raw) {
        if (raw == null) {
            return "";
        }
        String normalized = E164Telephone.normalize(raw);
        return normalized != null ? normalized : raw.trim();
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return "";
        }
        String trimmed = email.trim();
        return trimmed.isEmpty() ? "" : trimmed.toLowerCase(Locale.ROOT);
    }
}
===== AssignHouseholdId =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Runs after {@link BuildOwner} when the request set {@code sharesHousehold: true}: the new owner is
 * joining an existing household (another owner with the same last name at the same address). Assigns
 * a stable, shared {@code householdId} to the new owner and back-fills it onto the existing household
 * member(s), so every owner in the household reports the same identifier. The shared householdId then
 * forms part of each member's {@link OwnerIdentityKey identityKey}, so household members with
 * different telephones have different keys and are not treated as duplicates.
 *
 * <p>The identifier is derived deterministically from the normalized last name and address, so it is
 * stable across creations and identical for everyone in one household regardless of the order they
 * were added.
 */
public class AssignHouseholdId {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(owner.getLastName());
        String address = AddressNormalizer.normalize(owner.getAddress());
        String householdId = deriveHouseholdId(lastName, address);
        owner.setHouseholdId(householdId);
        // Back-fill the shared id onto the existing household member(s) so both sides match.
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))
                    && !householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }

    /** Stable 12-character upper-case hex identifier derived from the household's name and address. */
    private static String deriveHouseholdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "\n" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== CheckOwnerIdentityUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityConflictException;

/**
 * The single, consolidated duplicate check for {@code POST /api/owners}: rejects the request with
 * 409 when the new owner's whole {@link OwnerIdentityKey identityKey}
 * ({@code normalizedTelephone|email|householdId}) equals an existing owner's. This replaces the
 * former separate telephone, email and household checks; because the telephone is part of the key,
 * two members of one household (same householdId) with different telephones have different keys and
 * are both allowed — only an exact full-key match is a duplicate.
 *
 * <p>Runs after {@link AssignHouseholdId} so the householdId segment is populated before the key is
 * built, and before {@link SaveOwner} so the not-yet-saved owner is not compared against itself.
 */
public class CheckOwnerIdentityUnique {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws OwnerIdentityConflictException {
        String identityKey = OwnerIdentityKey.of(owner);
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                continue;
            }
            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
                throw new OwnerIdentityConflictException(
                        "An owner with identity " + identityKey + " already exists");
            }
        }
    }
}
===== AssignHouseholdMemberCount =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code householdMemberCount}: the number of owners in this owner's household
 * (all owners sharing the same {@code householdId}) once this create completes, including the new
 * owner itself. Runs after {@link AssignHouseholdId} has assigned and back-filled the shared
 * {@code householdId}, but before the new owner is saved, so the existing members are counted from
 * the repository and the not-yet-persisted new owner is added in as one.
 *
 * <p>An owner not joining a household has no {@code householdId}; its household is just itself, so
 * the count is 1.
 */
public class AssignHouseholdMemberCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        int count = 1; // the new owner, not yet saved
        if (householdId != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (householdId.equals(existing.getHouseholdId())) {
                    count++;
                }
            }
        }
        owner.setHouseholdMemberCount(count);
    }
}

